<template>
  <main class="pd2">
    <div class="pd2-topline">
      <nav aria-label="Đường dẫn"><router-link to="/">Trang chủ</router-link><span>/</span><router-link to="/tim-kiem">Sản phẩm</router-link><span>/</span><span>{{ product?.ten_san_pham || 'Chi tiết sản phẩm' }}</span></nav>
    </div>
    <div v-if="loading" class="pd2-state" role="status"><div class="pd2-skeleton"></div><p>Đang tải sản phẩm…</p></div>
    <div v-else-if="error" class="pd2-state" role="alert"><h1>Chưa thể hiển thị sản phẩm</h1><p>{{ error }}</p><button @click="retry">Thử lại</button><router-link to="/tim-kiem">Khám phá sản phẩm khác</router-link></div>
    <template v-else-if="product">
      <div class="pd2-grid">
        <section class="pd2-gallery" aria-label="Ảnh sản phẩm">
          <div class="pd2-gallery-layout"><div class="pd2-thumbnails" aria-label="Ảnh thu nhỏ"><button v-for="(image, index) in images" :key="image" :aria-label="'Xem ảnh ' + (index + 1)" :aria-pressed="imageIndex === index" @click="setImage(index)"><img :src="image" :alt="'Ảnh ' + (index + 1)" /></button><div v-if="!images.length" class="pd2-thumbnail-empty"><span>＋</span><small>CHỜ ẢNH</small></div></div><div class="pd2-stage">
            <span v-if="illustrativeImage" class="pd2-illustration-badge">Ảnh minh họa · không phải mẫu thực tế</span><span class="pd2-gallery-label">SOFEP / PRODUCT GALLERY</span>
            <button v-if="activeImage && !imageFailed" class="pd2-main-image" aria-label="Phóng to ảnh sản phẩm" @click="openZoom"><img :src="activeImage" :alt="product.ten_san_pham" @error="imageFailed = true" /></button>
            <div v-else class="pd2-no-image"><span class="pd2-placeholder-brand">S<span>✦</span></span><span class="pd2-section-kicker">PRODUCT IMAGE PENDING</span><strong>{{ imageFailed ? 'Ảnh tạm thời không khả dụng' : 'Chờ ảnh đúng sản phẩm' }}</strong><p>{{ product.ma_san_pham }}<br>Placeholder · Không phải ảnh sản phẩm</p></div>
            <button v-if="activeImage && !imageFailed" class="pd2-zoom-button" aria-label="Phóng to" @click="openZoom">↗ <span>Phóng to</span></button>
            <div v-if="images.length > 1" class="pd2-gallery-controls"><button aria-label="Ảnh trước" @click="moveImage(-1)">←</button><span>{{ imageIndex + 1 }} / {{ images.length }}</span><button aria-label="Ảnh tiếp theo" @click="moveImage(1)">→</button></div>
          </div>
          </div>
          <p v-if="illustrativeImage" class="pd2-image-notice" role="note">Ảnh minh họa kiểu áo, không phải mẫu SOFEP thực tế. Màu, chất liệu và chi tiết có thể khác. Các ảnh không phải các góc chụp của cùng một mẫu.</p>
          <p class="pd2-gallery-caption">{{ product.ten_san_pham }} <span>{{ images.length ? images.length + (illustrativeImage ? ' ảnh minh họa' : ' ảnh sản phẩm') : '' }}</span></p>
        <p v-if="unverifiedImages && !images.length" class="pd2-image-notice">ⓘ Ảnh stock trong catalog chưa được xác minh với SKU này nên không được dùng để minh họa sản phẩm.</p></section>
        <section class="pd2-info" aria-label="Thông tin và lựa chọn sản phẩm">
          <div class="pd2-eyebrow">SOFEP <span>{{ product.danh_muc?.ten_danh_muc || 'THE SOFEP EDIT' }}</span></div>
          <h1>{{ product.ten_san_pham }}</h1>
          <p v-if="product.ma_san_pham" class="pd2-sku">SKU <span>{{ product.ma_san_pham }}</span></p>
          <div class="pd2-social-proof"><span v-if="!rating.count" class="pd2-review-empty">Chưa có đánh giá hợp lệ</span>
            <button v-if="rating.count" class="pd2-rating" @click="activeTab = 'reviews'; scrollToInformation()"><span class="pd2-star">★</span><strong>{{ rating.average.toFixed(1) }}</strong><span>({{ rating.count }} đánh giá)</span></button>
            <span v-if="soldCount !== null" class="pd2-proof-divider"></span><span v-if="soldCount !== null" :title="soldDefinition">Đã bán <strong>{{ soldCount.toLocaleString('vi-VN') }}</strong></span>
          </div>
          <div class="pd2-pricing"><span class="pd2-price-label">GIÁ SẢN PHẨM</span><div><strong>{{ money(pricing.price) }}</strong><span v-if="pricing.saving > 0" class="pd2-original">{{ money(pricing.original) }}</span><span v-if="pricing.percent > 0" class="pd2-discount">−{{ pricing.percent }}%</span></div><p v-if="pricing.saving > 0">Tiết kiệm <strong>{{ money(pricing.saving) }}</strong> cho lựa chọn này</p></div>
          <p v-if="product.mo_ta_ngan" class="pd2-intro">{{ product.mo_ta_ngan }}</p>
          <div v-if="showColors" class="pd2-option-group"><div class="pd2-option-title">Màu sắc <strong>{{ colors.find(group => group.key === colorKey)?.color?.ten_mau || 'Chưa chọn' }}</strong></div><div class="pd2-swatches"><button v-for="group in colors" :key="group.key" :aria-label="'Chọn màu ' + (group.color?.ten_mau || 'Tiêu chuẩn')" :aria-pressed="colorKey === group.key" :title="group.color?.ten_mau || 'Tiêu chuẩn'" @click="chooseColor(group.key)"><span :style="{ backgroundColor: swatchColor(group.color?.ma_mau) }">{{ swatchColor(group.color?.ma_mau) ? '' : (group.color?.ten_mau || 'TC').slice(0, 2) }}</span><i v-if="colorKey === group.key">✓</i></button></div></div>
          <div v-if="showSizes" class="pd2-option-group"><div class="pd2-option-title">Size / Quy cách <strong>{{ sizes.find(variant => optionKey(variant.id_kich_thuoc) === sizeKey)?.kich_thuoc?.ten_kich_thuoc }}</strong><button v-if="sizeNotes.length" class="pd2-guide-link" @click="activeTab = 'size'; scrollToInformation()">Hướng dẫn size ↗</button></div><div class="pd2-size-list"><button v-for="variant in sizes" :key="variant.id" :aria-pressed="sizeKey === optionKey(variant.id_kich_thuoc)" :disabled="!sizeAvailable(variant)" @click="chooseSize(variant)">{{ variant.kich_thuoc?.ten_kich_thuoc || 'Tiêu chuẩn' }}<span v-if="!sizeAvailable(variant)" class="pd2-soldout-line"></span></button></div></div>
          <p v-if="hasOptions && !showColors && !showSizes" class="pd2-standard">Phiên bản tiêu chuẩn</p>
          <div class="pd2-stock" role="status"><i :class="{ empty: displayStock === 0 }"></i><span>{{ selectionPending ? 'Tổng tồn kho: ' + displayStock + ' sản phẩm' : displayStock > 0 ? 'Còn ' + displayStock + ' sản phẩm' : 'Tạm hết hàng' }}</span><small v-if="selectedVariant">Mã biến thể #{{ selectedVariant.id }}</small></div>
          <div class="pd2-purchase-row"><div class="pd2-quantity"><button aria-label="Giảm số lượng" :disabled="quantity <= 1" @click="quantity = Math.max(1, quantity - 1)">−</button><input v-model.number="quantity" aria-label="Số lượng" type="number" min="1" :max="maximumQuantity" step="1" @change="normalizeQuantity" @blur="normalizeQuantity" /><button aria-label="Tăng số lượng" :disabled="quantity >= maximumQuantity" @click="quantity = Math.min(maximumQuantity, quantity + 1)">+</button></div><button class="pd2-add" :disabled="!canPurchase" @click="purchase(false)"><span>+</span> Thêm vào giỏ</button></div>
          <button class="pd2-buy" :disabled="!canPurchase" @click="purchase(true)">Mua ngay <span>↗</span></button>
          <p v-if="stock > 0 && maximumQuantity === 0" class="pd2-purchase-message">Số lượng trong giỏ đã đạt tồn kho của lựa chọn này.</p>
          <p v-if="purchaseError" class="pd2-purchase-message" role="alert">{{ purchaseError }}</p>
        </section>
      </div>
      <section v-if="tabs.length" ref="information" class="pd2-information">
        <div class="pd2-tabs" role="tablist" aria-label="Thông tin bổ sung"><button v-for="tab in tabs" :id="'pd2-tab-' + tab.key" :key="tab.key" role="tab" :aria-selected="activeTab === tab.key" :aria-controls="'pd2-panel-' + tab.key" @click="activeTab = tab.key">{{ tab.label }}</button></div>
        <div :id="'pd2-panel-' + activeTab" role="tabpanel" :aria-labelledby="'pd2-tab-' + activeTab" class="pd2-tab-content">
          <template v-if="activeTab === 'description'"><p class="pd2-section-kicker">THE DETAILS</p><h2>Chi tiết tạo nên khác biệt.</h2><p class="pd2-description">{{ product.mo_ta_chi_tiet || product.mo_ta_ngan }}</p></template>
          <template v-if="activeTab === 'specs'"><h2>Thông số sản phẩm</h2><dl v-for="(value, key) in productFacts" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></dl></template>
          <template v-if="activeTab === 'size'"><h2>Thông tin kích thước</h2><p v-if="sizeGuide">{{ sizeGuide }}</p><dl v-for="note in sizeNotes" :key="note.id"><dt>{{ note.name }}</dt><dd>{{ note.description }}</dd></dl></template>
          <template v-if="activeTab === 'reviews'"><div class="pd2-review-heading"><h2>Trải nghiệm từ khách hàng.</h2><strong>{{ rating.average?.toFixed(1) }}<span> / 5 · {{ rating.count }} đánh giá</span></strong></div><article v-for="review in reviews" :key="review.id" class="pd2-review"><div><strong>{{ review.khach_hang?.ho_va_ten || 'Khách hàng' }}</strong><span class="pd2-star">{{ '★'.repeat(Number(review.so_sao)) }}</span></div><h3 v-if="review.tieu_de">{{ review.tieu_de }}</h3><p>{{ review.noi_dung }}</p></article><p v-if="rating.count > reviews.length" class="pd2-review-limit">Đang hiển thị {{ reviews.length }} đánh giá gần nhất.</p></template>
        </div>
      </section>
      <section v-if="related.length" class="pd2-related" aria-label="Sản phẩm liên quan"><div class="pd2-related-heading"><div><p class="pd2-section-kicker">CONTINUE EXPLORING</p><h2>Cùng bộ sưu tập.</h2></div><router-link to="/tim-kiem">Khám phá tất cả ↗</router-link></div><div class="pd2-related-grid"><router-link v-for="item in related" :key="item.id" :to="'/san-pham/' + (item.slug_san_pham || item.id)" class="pd2-related-card"><div class="pd2-related-image"><ProductImage v-if="productGallery(item).length" :src="productGallery(item)[0]" :alt="item.ten_san_pham" loading="lazy" /><span v-else>S<span>✦</span><small>CHỜ ẢNH ĐÚNG SẢN PHẨM</small></span></div><p>{{ item.danh_muc?.ten_danh_muc || product.danh_muc?.ten_danh_muc }}</p><h3>{{ item.ten_san_pham }}</h3><strong>{{ money(basePrice(item)) }}</strong><span class="pd2-related-link">Xem sản phẩm ↗</span></router-link></div></section>
    </template>
    <dialog ref="zoomDialog" class="pd2-lightbox" aria-label="Ảnh phóng to" @close="zoomed = false"><button class="pd2-lightbox-close" aria-label="Đóng ảnh phóng to" @click="$refs.zoomDialog.close()">×</button><div class="pd2-lightbox-toolbar"><span v-if="illustrativeImage">Ảnh minh họa · không phải mẫu thực tế</span><span>{{ imageIndex + 1 }} / {{ images.length }}</span><button @click="zoomed = !zoomed">{{ zoomed ? 'Thu nhỏ −' : 'Phóng to +' }}</button></div><div class="pd2-lightbox-stage"><img :src="activeImage" :alt="product?.ten_san_pham" :class="{ enlarged: zoomed }" /></div><div v-if="images.length > 1" class="pd2-lightbox-nav"><button aria-label="Ảnh trước trong phóng to" @click="moveImage(-1)">←</button><button aria-label="Ảnh tiếp theo trong phóng to" @click="moveImage(1)">→</button></div></dialog>
  </main>
</template>

<script>
import axios from 'axios';
import { isIllustrativeImage } from '../../services/productImages.js';
import ProductImage from '../shared/ProductImage.vue';
import { cartStore } from '../../stores/cartStore';
import { galleryOf, basePrice, variantsOf, hasVariants, availableStock, totalAvailableStock } from '../../services/productCatalog.js';
import { optionKey, colorGroups, sizeGroups, imageForColor, findVariant, remainingQuantity, discountFor, purchaseSelection, productGallery, relatedProducts } from '../../services/productDetail.js';

export default {
  name: 'ChiTietSanPham', components: { ProductImage },
  data() { return { cartStore, products: [], product: null, reviews: [], rating: { count: 0, average: null }, soldCount: null, soldDefinition: '', specifications: null, sizeGuide: null, colorKey: 'none', sizeKey: 'none', quantity: 1, imageIndex: 0, imageFailed: false, zoomed: false, activeTab: 'description', loading: true, error: '', purchaseError: '', requestId: 0 }; },
  computed: {
    illustrativeImage() { return isIllustrativeImage(this.activeImage); },
    currentId() { return this.$route.params.slug || this.$route.params.id; },
    images() { return productGallery(this.product); },
    unverifiedImages() { return galleryOf(this.product).length > this.images.length; },
    related() { return relatedProducts(this.products, this.product); },
    productFacts() { return { ...(this.product?.ma_san_pham ? { 'Mã sản phẩm': this.product.ma_san_pham } : {}), ...(this.product?.danh_muc?.ten_danh_muc ? { 'Danh mục': this.product.danh_muc.ten_danh_muc } : {}), ...(this.colors.filter(g => g.color).length ? { 'Màu sắc': this.colors.filter(g => g.color).map(g => g.color.ten_mau).join(', ') } : {}), ...(this.specifications || {}) }; },
    activeImage() { return this.images[this.imageIndex] || ''; },
    colors() { return colorGroups(this.product); },
    sizes() { return this.showColors && this.colorKey === null ? [] : sizeGroups(this.product, this.colorKey); },
    hasOptions() { return hasVariants(this.product); },
    showColors() { return this.colors.some(group => group.color); },
    showSizes() { return this.sizes.some(variant => variant.kich_thuoc); },
    selectedVariant() { return findVariant(this.product, this.colorKey, this.sizeKey); },
    selectionPending() { return (this.showColors && this.colorKey === null) || (this.showSizes && this.sizeKey === null); },
    stock() { return availableStock(this.product, this.selectedVariant); },
    displayStock() { return this.selectionPending ? totalAvailableStock(this.product) : this.stock; },
    maximumQuantity() { return this.product ? remainingQuantity(this.product, this.selectedVariant, this.cartStore.items) : 0; },
    pricing() { return discountFor(this.product, this.selectedVariant); },
    canPurchase() { return !!this.product && (!this.hasOptions || !!this.selectedVariant) && Number.isInteger(this.quantity) && this.quantity > 0 && this.quantity <= this.maximumQuantity; },
    sizeNotes() { return [...new Map(variantsOf(this.product).filter(v => v.kich_thuoc?.mo_ta).map(v => [v.id_kich_thuoc, { id: v.id_kich_thuoc, name: v.kich_thuoc.ten_kich_thuoc, description: v.kich_thuoc.mo_ta }])).values()]; },
    tabs() { return [
      ...(this.product?.mo_ta_chi_tiet || this.product?.mo_ta_ngan ? [{ key: 'description', label: 'Mô tả sản phẩm' }] : []),
      ...(Object.keys(this.productFacts).length ? [{ key: 'specs', label: 'Thông số' }] : []),
      ...(this.sizeGuide || this.sizeNotes.length ? [{ key: 'size', label: 'Hướng dẫn size' }] : []),
      ...(this.rating.count ? [{ key: 'reviews', label: `Đánh giá (${this.rating.count})` }] : [])
    ]; }
  },
  watch: { '$route.fullPath'() { if (this.currentId) this.loadProduct(this.currentId); } },
  mounted() { document.addEventListener('keydown', this.onKeydown); this.loadProduct(this.currentId); },
  beforeUnmount() { this.requestId++; document.removeEventListener('keydown', this.onKeydown); this.$refs.zoomDialog?.close(); },
  methods: {
    optionKey, productGallery, basePrice,
    money(value) { return Number(value || 0).toLocaleString('vi-VN', { maximumFractionDigits: 2 }) + '₫'; },
    swatchColor(value) { return /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(value || '') ? value : null; },
    retry() { return this.loadProduct(this.currentId); },
    async loadProduct(id) {
      const request = ++this.requestId;
      this.loading = true; this.error = ''; this.product = null; this.products = []; this.purchaseError = ''; this.$refs.zoomDialog?.close();
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/client/san-pham/' + encodeURIComponent(id) + '?presentation=2');
        if (request !== this.requestId) return;
        if (!response.data.status || !response.data.data?.san_pham) throw new Error('Invalid product');
        const data = response.data.data;
        this.product = data.san_pham; this.products = data.san_pham_lien_quan || []; this.reviews = data.reviews || []; this.rating = data.rating || { count: 0, average: null };
        this.soldCount = data.sold_count ?? null; this.soldDefinition = data.sold_definition;
        this.specifications = data.specifications; this.sizeGuide = data.size_guide;
        this.colorKey = this.showColors ? null : 'none';
        this.sizeKey = this.showSizes ? null : 'none';
        this.quantity = 1; this.imageIndex = 0; this.imageFailed = false;
        this.activeTab = this.tabs[0]?.key || '';
      } catch (error) { if (request === this.requestId) this.error = error.response?.status === 404 ? 'Sản phẩm không tồn tại hoặc đã ngừng bán.' : 'Không thể tải sản phẩm. Vui lòng thử lại.'; }
      finally { if (request === this.requestId) this.loading = false; }
    },
    chooseColor(key) {
      this.colorKey = key;
      if (!this.showSizes) this.sizeKey = 'none';
      else if (!this.selectedVariant) this.sizeKey = null;
      const index = this.images.indexOf(imageForColor(this.product, key));
      this.setImage(index >= 0 ? index : 0);
      this.quantity = 1; this.purchaseError = '';
    },
    sizeAvailable(variant) {
      const key = optionKey(variant.id_kich_thuoc);
      if (this.colorKey !== null) return Number(findVariant(this.product, this.colorKey, key)?.so_luong_ton) > 0;
      return variantsOf(this.product).some(item => optionKey(item.id_kich_thuoc) === key && Number(item.so_luong_ton) > 0);
    },
    chooseSize(variant) { this.sizeKey = optionKey(variant.id_kich_thuoc); this.quantity = 1; this.purchaseError = ''; },
    normalizeQuantity() { this.quantity = Math.max(1, Math.min(this.maximumQuantity || 1, Math.floor(Number(this.quantity) || 1))); },
    setImage(index) { this.imageIndex = index; this.imageFailed = false; },
    moveImage(direction) { if (this.images.length) this.setImage((this.imageIndex + direction + this.images.length) % this.images.length); },
    openZoom() { this.zoomed = false; this.$refs.zoomDialog.showModal(); },
    onKeydown(event) { if (!this.$refs.zoomDialog?.open) return; if (event.key === 'ArrowLeft') this.moveImage(-1); if (event.key === 'ArrowRight') this.moveImage(1); },
    scrollToInformation() { this.$nextTick(() => this.$refs.information.scrollIntoView({ behavior: 'smooth', block: 'start' })); },
    purchase(buyNow) {
      if (!this.canPurchase || !purchaseSelection(this.cartStore, this.product, this.selectedVariant, this.quantity, buyNow)) { this.purchaseError = 'Vui lòng chọn biến thể còn hàng và số lượng hợp lệ.'; return; }
      this.purchaseError = '';
      if (!buyNow) this.$toast?.success('Đã thêm đúng lựa chọn vào giỏ hàng.');
    }
  }
};
</script>

<style scoped>
.pd2{--ink:#191919;--muted:#73736f;--line:#e9e7e2;--gold:#ab8956;--champagne:#f5f0e7;max-width:1320px;margin:0 auto;padding:0 36px 80px;color:var(--ink);font-family:'Plus Jakarta Sans',sans-serif}
.pd2 button,.pd2 select,.pd2 input{font:inherit}.pd2 button{cursor:pointer;transition:background .18s,border-color .18s}.pd2 button:disabled{cursor:not-allowed;opacity:.4}.pd2 a{color:inherit;text-decoration:none}.pd2 button:focus-visible,.pd2 select:focus-visible,.pd2 input:focus-visible{outline:2px solid var(--gold);outline-offset:4px}
.pd2-lab{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:19px 0;font-size:10px;font-weight:600;letter-spacing:1.6px}.pd2-lab>span:first-child{display:flex;align-items:center;gap:10px}.pd2-lab>span:last-child{letter-spacing:.3px;color:var(--muted)}.pd2-lab b{color:#c3bfb7;margin:0 3px;font-weight:400}.pd2-lab i,.pd2-stock i{display:inline-block;width:6px;height:6px;background:var(--gold);border-radius:50%;flex-shrink:0}
.pd2-topline{display:flex;justify-content:space-between;gap:24px;padding:25px 0 30px;align-items:center}.pd2-topline nav{display:flex;gap:12px;font-size:11px;align-items:center;color:var(--muted);flex-wrap:wrap}.pd2-topline nav span:nth-child(even){color:#c7c5c0}.pd2-topline label{display:flex;gap:10px;align-items:center;color:var(--muted);font-size:10px;white-space:nowrap}.pd2-topline select{background:white;border:1px solid var(--line);border-radius:4px;padding:8px;max-width:220px;color:var(--ink);font-size:11px}
.pd2-grid{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,1fr);gap:70px;align-items:start}.pd2-gallery{position:sticky;top:24px}.pd2-stage{position:relative;background:#f5f4f1;border:1px solid #efeeeb;aspect-ratio:4/4.65;overflow:hidden}.pd2-gallery-label{position:absolute;top:22px;left:22px;letter-spacing:2px;font-size:8px;z-index:1;color:#77766d;pointer-events:none}.pd2-main-image{display:block;border:0;background:transparent;width:100%;height:100%;padding:0;cursor:zoom-in!important}.pd2-main-image img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply}.pd2-no-image{display:flex;align-items:center;justify-content:center;height:100%;font-size:13px;color:var(--muted)}.pd2-zoom-button{position:absolute;right:18px;bottom:18px;background:#ffffffed;border:1px solid #fff;border-radius:30px;padding:9px 15px;font-size:16px}.pd2-zoom-button span{font-size:10px;margin-left:5px}.pd2-gallery-controls{position:absolute;bottom:18px;left:18px;background:#ffffffed;display:flex;align-items:center;gap:8px;padding:4px;border-radius:25px}.pd2-gallery-controls button{border:0;background:none;width:30px;height:30px}.pd2-gallery-controls span{font-size:10px;min-width:35px;text-align:center}.pd2-thumbnails{display:flex;gap:10px;margin-top:13px;overflow-x:auto;padding:2px}.pd2-thumbnails button{border:1px solid transparent;background:#f5f4f1;flex:0 0 72px;height:83px;padding:3px}.pd2-thumbnails button[aria-pressed=true]{border-color:var(--ink)}.pd2-thumbnails img{width:100%;height:100%;object-fit:contain}.pd2-gallery-caption{font-size:9px;color:#8b8983;display:flex;justify-content:space-between;gap:20px;margin:15px 0 0}
